UPDATE TB_PJ_WEEK_MEMO SET THIS_WEEK_CN=#{input.workDone},NEXT_WEEK_CN=#{input.nextWork},
  REQ_CN=#{input.requests},ACTL_PRGRS_RT=#{input.actualProgress,jdbcType=NUMERIC},
  MOD_USER_ID=#{actor},MOD_DTTM=#{now}
WHERE PROJ_ID=#{projectId} AND MEMO_SN=#{sequence}

UPDATE TB_PJ_STEP SET PLAN_BGN_DT=#{dates.plannedStartDate},PLAN_END_DT=#{dates.plannedEndDate},
  MOD_USER_ID=#{actor},MOD_DTTM=#{now}
WHERE PROJ_ID=#{projectId} AND STEP_SN=CAST(#{dates.stepId} AS numeric) AND CMPL_DT IS NULL
